const BACKGROUND='A new dam has been proposed near the village. It could provide water storage and electricity, but may also affect the river and nearby communities. Four stakeholder groups meet to consider the proposal and its alternatives.';
const STAGE_LINES={lobby:'Four groups arrive at the village meeting to consider a proposed dam.', 'first-vote':'Before meeting with your group, make your own initial decision.',discussion:'Meet with your group and guide to prepare a recommendation and choose a student spokesperson.',debate:'Student spokespeople present at the village conference. Listen, ask questions, and consider other groups.', 'final-vote':'After the conference, make your own final decision.',results:'Explore two possible futures and discuss benefits, costs, and whose needs are protected.'};
const HOST_LINES={lobby:'Welcome to the village conference. We are your conference chairs today. Each group brings different needs and concerns about water, electricity, livelihoods, and the environment.', 'first-vote':'Make your initial decision individually. Your choice will appear on the screen. If you support the dam with conditions, write a specific condition before submitting.',discussion:'Guides, help everyone contribute. Consider benefits, costs, and alternatives. Choose one student spokesperson for your group. Your guide helps the discussion and does not speak or decide for you.',debate:'Each student spokesperson, present your recommendation, reasons, and any conditions. Other groups may ask questions. We will make room for different views before voting again.', 'final-vote':'Vote individually again. You may keep or change your decision. Conditional support still needs a written condition.',results:'These are illustrative possibilities, not predictions. The reactions show how roles might feel, not who was right. Consider both benefits and costs in each future.'};
function stageStory(host=false){const intro=['lobby','first-vote'].includes(state.phase),line=host?({lobby:'Welcome the four stakeholder groups and introduce the shared proposal.', 'first-vote':'Invite students to make their initial decisions individually.', 'final-vote':'Invite students to make their final decisions individually.'}[state.phase]||STAGE_LINES[state.phase]):state.me.kind==='guide'?({'first-vote':'Observe the first vote. You guide the group and do not vote.', 'final-vote':'Give students space to decide individually. You do not vote.'}[state.phase]||STAGE_LINES[state.phase]):STAGE_LINES[state.phase];return '<section class="card stage-story">'+(intro?'<p class="background">'+esc(BACKGROUND)+'</p>':'')+'<p class="stage-line">'+esc(line)+'</p>'+(host?'<details class="host-script"><summary>Conference chair script</summary><p>'+esc(HOST_LINES[state.phase])+'</p><p><b>Follow up:</b> Thank you for explaining your reasoning. Which evidence supports it, and how would another group respond?</p></details>':'')+'</section>'}
