let state=null,session=null,busy=false,lastSignature='',clockOffset=0,guideKeys=null,lastBeat=0,pollBusy=false,avatarPositions=new Map(),avatarVotes=new Map(),conditionQueue=[],activeCondition=null,conditionRound=-1,conditionEditingKey=null,conditionDrafts=new Map();
const queryView=new URLSearchParams(location.search).get('view'),path=location.pathname,mode=queryView==='host'||path==='/admin'?'host':queryView==='guide'||path==='/guide'?'guide':'student';
const API_ORIGIN=document.querySelector('meta[name="dam-api-origin"]')?.content||'';
function route(view='student',room=null){const url=new URL(API_ORIGIN?location.pathname: (view==='host'?'/admin':view==='guide'?'/guide':'/'),location.origin);if(API_ORIGIN&&view!=='student')url.searchParams.set('view',view);if(room)url.searchParams.set('room',room);return url.href;}
function storageGet(k){try{return localStorage.getItem(k)}catch{return null}}function storageSet(k,v){try{localStorage.setItem(k,v)}catch{}}
function randomKey(){return [...crypto.getRandomValues(new Uint8Array(32))].map(n=>n.toString(16).padStart(2,'0')).join('')}
const storageKey='dam-village-'+mode;
try{session=JSON.parse(storageGet(storageKey)||'null')}catch{}
const params=new URLSearchParams(location.search);if(params.has('room')&&session?.room!==params.get('room').toUpperCase())session=null;
function announce(s){$('#toast').textContent=s}function error(s){const e=$('#error');if(e)e.textContent=s;announce(s)}
async function call(endpoint,body,credential=session){const headers={'content-type':'application/json'};if(credential?.key)headers.authorization='Bearer '+credential.key;const response=await fetch(API_ORIGIN+'/api/'+endpoint+(body?'':'?room='+encodeURIComponent(credential?.room||'')),{method:body?'POST':'GET',headers,...(body?{body:JSON.stringify({...body,room:body.room||credential?.room})}:{})});let r;try{r=await response.json()}catch{throw Error('The classroom service is unavailable. Please retry.')}if(!response.ok){let e=Error(r.error||'Please retry.');e.status=response.status;throw e}return r}
